(()=>{'use strict';
 const $=s=>document.querySelector(s);
 const pending=()=>typeof tasks==='undefined'?[]:tasks.filter(t=>t.status==='review'&&reviewer(t));
 const icon=()=>'<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3 4 7v5c0 5.1 3.4 8.4 8 9 4.6-.6 8-3.9 8-9V7l-8-4Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/></svg>';
 function add(){const nav=$('#deskNav');if(!nav)return;let b=$('#deskApprovals');if(!b){b=document.createElement('button');b.id='deskApprovals';b.type='button';b.dataset.deskView='approvals';b.innerHTML=icon()+'<span>نیازمند تأیید</span><b data-desk-count="approvals"></b>';b.onclick=()=>{if(!management())return;scope='approvals';phase='all';search='';render()};nav.querySelector('[data-desk-view="all"]')?.after(b)}b.hidden=!management()}
 function row(t){const team=t.collaborators?.length?' · همکاران: '+t.collaborators.map(person).map(esc).join('، '):'';const description=t.description?'<p>'+esc(t.description)+'</p>':'';return '<article class="approval-row" data-approval-task="'+t.id+'"><div class="approval-row-main"><strong>'+esc(t.title)+'</strong>'+description+'<small>مسئول: '+esc(person(t.owner_id))+team+'</small></div><div class="approval-row-actions"><span>ارسال‌شده برای تأیید</span><button class="secondary" type="button" data-open-approval="'+t.id+'">بررسی</button><button class="primary" type="button" data-approve-approval="'+t.id+'">تأیید نهایی</button></div></article>'}
 function draw(){if(scope!=='approvals'||!project||!mine())return;const rows=pending(),badge=$('[data-desk-count="approvals"]');$('#deskCrumb').textContent='نیازمند تأیید';document.querySelectorAll('[data-desk-view]').forEach(b=>b.classList.toggle('active',b.dataset.deskView==='approvals'));if(badge)badge.textContent=fa(rows.length);const body=rows.length?'<div class="approval-list">'+rows.map(row).join('')+'</div>':'<div class="approval-empty"><b>کاری منتظر تأیید شما نیست.</b><span>وقتی همکاری کاری را برای تأیید بفرستد، اینجا می‌بینید.</span></div>';$('#sharedContent').innerHTML='<section class="approval-inbox"><div class="desk-shared-heading"><small>مدیریت پروژه / بررسی نهایی</small><h1>نیازمند تأیید</h1><p>کارهایی که برای تأیید نهایی به شما ارسال شده‌اند.</p></div>'+body+'</section>';document.querySelectorAll('[data-open-approval]').forEach(b=>b.onclick=e=>{e.stopPropagation();detail(b.dataset.openApproval)});document.querySelectorAll('[data-approve-approval]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const t=tasks.find(x=>x.id===b.dataset.approveApproval);if(t)await action(t,'approve')});document.querySelectorAll('[data-approval-task]').forEach(node=>node.onclick=e=>{if(!e.target.closest('button'))detail(node.dataset.approvalTask)})}
 const previous=render;render=function(...args){const value=previous(...args);add();const badge=$('[data-desk-count="approvals"]');if(badge)badge.textContent=fa(pending().length);if(scope==='approvals')draw();return value};add();
})();
